ControlPropertyState.AutoRuleBindingString:
UpdateContext({ ctxAbandonoOkSes: true });

// ============================================================================
// 1. RE-LECTURA POR PK (Q9). Entre que el cajero abrio el dialogo y confirmo,
//    el supervisor pudo resolver. Cancelar una solicitud YA RESUELTA seria
//    borrar la evidencia de una decision del supervisor.
// ============================================================================
If(
    !IsBlank(gvarSolicitud.'CH-Tbl-ApprovalRequest'),
    Set(
        gvarSolicitud,
        LookUp(
            'CH-Tbl-ApprovalRequests',
            'CH-Tbl-ApprovalRequest' = gvarSolicitud.'CH-Tbl-ApprovalRequest'
        )
    )
);

If(
    // ========================================================================
    // CARRERA (solo posible desde A2): ya la resolvieron. NO se borra NADA.
    //   El timer sigue armado —su Start es ctxEsperandoSes (§10)— y en el
    //   proximo tick pinta el estado real. Como mucho, 15 segundos.
    // ========================================================================
    ctxEsperandoSes && !IsBlank(gvarSolicitud.'CH-Tbl-ApprovalRequest') && !IsBlank(gvarSolicitud.ApprovalStatus),
        Notify(
            "El supervisor ya resolvió la solicitud: la pantalla se actualiza sola en unos segundos.",
            NotificationType.Information
        ),

    // ========================================================================
    // ABANDONO REAL
    // ========================================================================
    // ---- 1. La solicitud primero: sale de la cola del supervisor (Q8) -------
    //    GATE DOBLE — PK **y** estado:
    //      · PK: la existencia se pregunta por 'CH-Tbl-ApprovalRequest', nunca
    //        con IsBlank(<registro>), que sobre un registro tipado vacio puede
    //        devolver false.
    //      · Estado: SOLO se borra una solicitud sin resolver. Desde A3 la
    //        solicitud esta RECHAZADA: es la evidencia de una decision del
    //        supervisor y se conserva como registro (D02-5). Esa rama se SALTEA,
    //        ctxAbandonoOkSes queda en true y los pasos 2 y 3 siguen.
    If(
        !IsBlank(gvarSolicitud.'CH-Tbl-ApprovalRequest') &&
        IsBlank(gvarSolicitud.ApprovalStatus),
        IfError(
            Remove('CH-Tbl-ApprovalRequests', gvarSolicitud),
            Notify("No se pudo cancelar la solicitud: " & FirstError.Message, NotificationType.Error);
            UpdateContext({ ctxAbandonoOkSes: false })
        )
    );

    // ---- 2. La sesion despues: libera la mesa (Q7) --------------------------
    If(
        ctxAbandonoOkSes,
        IfError(
            Remove('CH-Tbl-RecountingSessions', gvarSesion),
            Notify("No se pudo liberar la mesa: " & FirstError.Message, NotificationType.Error);
            UpdateContext({ ctxAbandonoOkSes: false })
        )
    );

    // ---- 3. Solo con las DOS bajas hechas se vuelve al estado inicial -------
    //    El catalogo se recompone en MEMORIA (cero red): se quita la sesion
    //    liberada de colSesionesHoySes y se recalcula colMesasSes desde el
    //    snapshot colMesasDVSes que el OnVisible ya dejo cargado.
    If(
        ctxAbandonoOkSes,
        Remove(
            colSesionesHoySes,
            LookUp(
                colSesionesHoySes,
                'CH-Tbl-RecountingSession' = gvarSesion.'CH-Tbl-RecountingSession'
            )
        );
        ClearCollect(
            colMesasSes,
            Filter(
                colMesasDVSes As M,
                IsBlank(
                    LookUp(
                        colSesionesHoySes,
                        CountingDesk.'CH-Tbl-CountingDesk' = M.'CH-Tbl-CountingDesk'
                    )
                )
            )
        );
        Set(gvarSolicitud, Blank());
        Set(gvarSesion,    Blank());
        Set(gvarMesa,      Blank());
        // El aviso se emite ANTES de bajar las banderas: desde A3 la solicitud
        // rechazada NO se borro, y decir "solicitud cancelada" seria mentir.
        Notify(
            If(
                ctxRechazadaSes,
                "Mesa liberada. La solicitud rechazada queda registrada. Elija otra mesa.",
                "Solicitud cancelada. Elija otra mesa."
            ),
            NotificationType.Information
        );
        UpdateContext({ ctxEsperandoSes: false, ctxRechazadaSes: false });
        Reset(ddMesaSes)
    )
)

// ============================================================================
// BLOQUE 0 — ESTADO DE UI. Corre SIEMPRE, tambien con la identidad rota.
//   El estado de los dialogos PERSISTE entre visitas: sin este reset, volver
//   aca desde scrTulas te encuentra el modal de cancelacion abierto.
// ============================================================================
UpdateContext({
    ctxEsperandoSes:   false,
    ctxRechazadaSes:   false,
    ctxDlgCancelarSes: false,
    ctxAbandonoOkSes:  true
});

// ============================================================================
// GUARDA DURA DE IDENTIDAD (01 §3.2, ledger L-16).
//   Con gvarIdentidadOk = false, cntBloqueoSes (§11) tapa la pantalla y NINGUNA
//   consulta de abajo tiene sentido: gvarUser esta en blanco y
//   Cashier.User = Blank() devolveria basura. Ese era el bypass S-1 de la v1.
//   No hay Navigate ni salida: la app se BLOQUEA, no degrada.
// ============================================================================
If(
    gvarIdentidadOk,

    // ========================================================================
    // BLOQUE 1 — CATALOGO DE MESAS DISPONIBLES.  Q3 + Q4 (§2), delegables.
    //   Se carga SIEMPRE, en los tres estados: "Cancelar solicitud" y "Elegir
    //   otra mesa" (§9) devuelven la tarjeta al estado inicial SIN volver a la
    //   red y necesitan el catalogo ya en memoria (regla D-10).
    //
    //   La resta "mesas habilitadas MENOS mesas con sesion de hoy" es LOCAL:
    //   en el servidor exigiria un `in` con subconsulta, que JAMAS delega (D-6).
    // ========================================================================
    ClearCollect(
        colSesionesHoySes,
        Filter(
            'CH-Tbl-RecountingSessions',
            'Created On' >= Today() &&
            'Created On' <  DateAdd(Today(), 1, TimeUnit.Days) &&
            SessionForciblyClosed = false
        )
    );
    ClearCollect(
        colMesasDVSes,
        Sort(
            Filter('CH-Tbl-CountingDesks', Enable = true),
            Name
        )
    );
    ClearCollect(
        colMesasSes,
        Filter(
            colMesasDVSes As M,
            IsBlank(
                LookUp(
                    colSesionesHoySes,
                    CountingDesk.'CH-Tbl-CountingDesk' = M.'CH-Tbl-CountingDesk'
                )
            )
        )
    );

    // ========================================================================
    // BLOQUE 2 — LA SESION DE HOY DEL CAJERO.  Q1 (§2), delegable.
    //   Sort + First, nunca LookUp a secas (regla D-9): si por un fallo previo
    //   hay mas de una sesion del dia, la que manda es la ULTIMA.
    // ========================================================================
    Set(
        gvarSesion,
        First(
            Sort(
                Filter(
                    'CH-Tbl-RecountingSessions',
                    Cashier.User = gvarUser.User &&
                    'Created On' >= Today() &&
                    'Created On' <  DateAdd(Today(), 1, TimeUnit.Days) &&
                    SessionForciblyClosed = false
                ),
                'Created On',
                SortOrder.Descending
            )
        )
    );

    // ========================================================================
    // BLOQUE 3 — LA SOLICITUD DE ESA SESION.  Q2 (§2), delegable.
    //   El If va POR FUERA del Set: sin sesion no hay nada que recuperar y la
    //   consulta ni se dispara. La existencia se pregunta SIEMPRE por la PK.
    // ========================================================================
    If(
        IsBlank(gvarSesion.'CH-Tbl-RecountingSession'),
        Set(gvarSolicitud, Blank()),
        Set(
            gvarSolicitud,
            First(
                Sort(
                    Filter(
                        'CH-Tbl-ApprovalRequests',
                        'Created By'.User = gvarUser.User &&
                        RequestType = "Crear sesion de recuento" &&
                        'Created On' >= Today() &&
                        'Created On' <  DateAdd(Today(), 1, TimeUnit.Days)
                    ),
                    'Created On',
                    SortOrder.Descending
                )
            )
        )
    );

    // ========================================================================
    // BLOQUE 4 — MAQUINA DE ESTADOS. Cuatro ramas, y ninguna mas.
    //   El RECHAZO es un estado de PRIMERA CLASE (mata S-4). La v1 preguntaba
    //   `ApprovalStatus = Blank()` y fallaba ABIERTO: un rechazo liberaba al
    //   cajero exactamente igual que una aprobacion.
    // ========================================================================
    If(
        // ---- 1. AVALADA POR EL SERVIDOR: se entra sin ver esta pantalla ------
        //    `Confirmed` lo escribe el PLUGIN (01 §2.4). La app nunca lo toca.
        !IsBlank(gvarSesion.'CH-Tbl-RecountingSession') &&
        (
            gvarSesion.Confirmed = true ||
            gvarSolicitud.ApprovalStatus = 'ApprovalStatus (CH-Tbl-ApprovalRequests)'.Aprobado
        ),
            // ---- contrato de salida, copia literal de 01 §4.5 ----
            Set(gvarMesa, gvarSesion.CountingDesk);
            Set(gvarTula, Blank());
            Set(gvarSesionDetalle, Blank());
            Set(gvarDeclaredBag, Blank());
            Set(gvarSolicitud, Blank());
            Navigate(scrTulas),

        // ---- 2. RECHAZADA: BLOQUEA, no libera -------------------------------
        !IsBlank(gvarSesion.'CH-Tbl-RecountingSession') &&
        gvarSolicitud.ApprovalStatus = 'ApprovalStatus (CH-Tbl-ApprovalRequests)'.Rechazado,
            Set(gvarMesa, gvarSesion.CountingDesk);
            UpdateContext({ ctxEsperandoSes: false, ctxRechazadaSes: true }),

        // ---- 3. PENDIENTE: el cajero cerro la app mientras esperaba ----------
        //    El timer arranca solo: su Start es ctxEsperandoSes (§10).
        !IsBlank(gvarSesion.'CH-Tbl-RecountingSession') &&
        !IsBlank(gvarSolicitud.'CH-Tbl-ApprovalRequest'),
            Set(gvarMesa, gvarSesion.CountingDesk);
            UpdateContext({ ctxEsperandoSes: true, ctxRechazadaSes: false }),

        // ---- 4. INICIAL -----------------------------------------------------
        //    Incluye el caso raro "sesion de hoy SIN solicitud" (el Patch de la
        //    solicitud fallo Y la compensacion de §8 tambien). Se degrada al
        //    estado inicial CON AVISO: la app no borra sola una sesion que no
        //    sabe quien creo. Divergencia D02-18.
        If(
            !IsBlank(gvarSesion.'CH-Tbl-RecountingSession'),
            Notify(
                "Tiene una sesión de hoy sin solicitud de aprobación: esa mesa puede aparecer ocupada. Elija otra mesa y avise al supervisor.",
                NotificationType.Warning
            )
        );
        Set(gvarSesion,    Blank());
        Set(gvarMesa,      Blank());
        Set(gvarSolicitud, Blank());
        UpdateContext({ ctxEsperandoSes: false, ctxRechazadaSes: false })
    )
);

// ============================================================================
// BLOQUE 5 — RESET DE CONTROLES. SIEMPRE, y al final.
//   El desplegable clasico recuerda su seleccion entre visitas: sin el Reset,
//   volver aca tras cerrar una sesion deja marcada una mesa que ya no esta en
//   colMesasSes.
// ============================================================================
Reset(ddMesaSes)
